baseline.py:
"""Simple deterministic invoice parser over canonical OCR lines."""

from __future__ import annotations

import re
from dataclasses import replace

from .contracts import (
    CONTRACT_VERSION,
    HEADER_FIELDS,
    DocumentPage,
    FieldValue,
    InvoiceRecord,
    LineItem,
    TextSpan,
    missing,
)

BASELINE_VERSION = "ocr-rules-v0.3"

LABELS = {
    "invoice_number": re.compile(r"^invoice\s*(?:number|no\.?|#)\s*:\s*(.+)$", re.I),
    "issue_date": re.compile(r"^(?:issue\s*)?date\s*:\s*(.+)$", re.I),
    "due_date": re.compile(r"^due\s*date\s*:\s*(.+)$", re.I),
    "currency": re.compile(r"^currency\s*:\s*(.+)$", re.I),
    "subtotal": re.compile(r"^subtotal\s*:\s*(.+)$", re.I),
    "tax": re.compile(r"^tax\s*:\s*(.+)$", re.I),
    "discount": re.compile(r"^discount\s*:\s*(.+)$", re.I),
    "shipping": re.compile(r"^shipping\s*:\s*(.+)$", re.I),
    "total": re.compile(r"^total\s*:\s*(.+)$", re.I),
}
ROW = re.compile(r"^(.+?)\s+(\d+(?:\.\d+)?)\s+(\d+\.\d{2})\s+(\d+\.\d{2})$")
ROW_WITHOUT_TOTAL = re.compile(r"^(.+?)\s+(\d+(?:\.\d+)?)\s+(\d+\.\d{2})$")
AMOUNT_ONLY = re.compile(r"^\d+\.\d{2}$")


def observed(value: str, span: TextSpan) -> FieldValue:
    return FieldValue(value=value.strip(), raw=span.text, evidence_ids=(span.id,))


def extract_invoice(page: DocumentPage) -> InvoiceRecord:
    fields = {name: missing() for name in HEADER_FIELDS}
    for span in page.spans:
        line = span.text.strip()
        if not line:
            continue
        matched = False
        for name, pattern in LABELS.items():
            match = pattern.fullmatch(line)
            if match:
                if fields[name].value is None:
                    fields[name] = observed(match.group(1), span)
                matched = True
                break
        if matched:
            continue
        # Tesseract can emit a clipped page-corner glyph before the actual
        # printed header. A source box touching both top and left edges is
        # unreliable as a supplier name.
        corner_artifact = span.box is not None and span.box.top <= .005 and span.box.left <= .005
        if fields["supplier_name"].value is None and line.lower() != "invoice" and not corner_artifact:
            fields["supplier_name"] = observed(re.sub(r"\s+INVOICE$", "", line, flags=re.I), span)
    return InvoiceRecord(CONTRACT_VERSION, fields, _extract_rows(page))


def extract_invoice_pages(pages: tuple[DocumentPage, ...]) -> InvoiceRecord:
    """Apply the narrow baseline per page, retaining source order and page spans."""
    if not pages:
        raise ValueError("At least one page is required")
    fields = {name: missing() for name in HEADER_FIELDS}
    rows: list[LineItem] = []
    for page in pages:
        candidate = extract_invoice(page)
        for name in HEADER_FIELDS:
            if fields[name].value is None and candidate.fields[name].value is not None:
                fields[name] = candidate.fields[name]
        for row in candidate.line_items:
            rows.append(replace(row, row_id=f"row-{len(rows) + 1:03d}"))
    return InvoiceRecord(CONTRACT_VERSION, fields, tuple(rows))


def _extract_rows(page: DocumentPage) -> tuple[LineItem, ...]:
    amount_spans = [span for span in page.spans if span.box and AMOUNT_ONLY.fullmatch(span.text.strip())]
    used_amounts: set[str] = set()
    candidates: list[tuple[float, LineItem]] = []
    for span in page.spans:
        line = span.text.strip()
        match = ROW.fullmatch(line)
        if match:
            description, quantity, unit_price, line_total = match.groups()
            total = observed(line_total, span)
        else:
            match = ROW_WITHOUT_TOTAL.fullmatch(line)
            if match is None or span.box is None:
                continue
            description, quantity, unit_price = match.groups()
            center = (span.box.top + span.box.bottom) / 2
            same_row = [
                candidate for candidate in amount_spans
                if candidate.id not in used_amounts
                and candidate.box is not None
                and candidate.box.left > span.box.right
                and abs((candidate.box.top + candidate.box.bottom) / 2 - center) <= .015
            ]
            if same_row:
                right = min(same_row, key=lambda candidate: candidate.box.left)
                used_amounts.add(right.id)
                total = observed(right.text.strip(), right)
            else:
                total = missing("rightmost_amount_not_observed")
        row = LineItem(
            row_id="pending",
            description=observed(description, span),
            quantity=observed(quantity, span),
            unit_price=observed(unit_price, span),
            line_total=total,
            tax=missing("not_explicit_on_row"),
        )
        candidates.append((span.box.top if span.box else float(len(candidates)), row))
    return tuple(replace(row, row_id=f"row-{index:03d}") for index, (_, row) in enumerate(sorted(candidates, key=lambda pair: pair[0]), start=1))

contracts.py:
"""Small, strict contracts shared by OCR, extraction, and validation.

Coordinates refer to the raster supplied to OCR, with a top-left origin. The
v1 parser must correct page rotation before constructing this contract.
Persistent schema comes later.
"""

from __future__ import annotations

from dataclasses import asdict, dataclass
from typing import Literal


HEADER_FIELDS = (
    "supplier_name",
    "invoice_number",
    "issue_date",
    "due_date",
    "currency",
    "subtotal",
    "tax",
    "discount",
    "shipping",
    "total",
)
REQUIRED_FIELDS = ("supplier_name", "invoice_number", "issue_date", "currency", "total")
CONTRACT_VERSION = "invoice-v1-spike"


@dataclass(frozen=True, slots=True)
class Box:
    left: float
    top: float
    right: float
    bottom: float

    def __post_init__(self) -> None:
        if not (0 <= self.left < self.right <= 1 and 0 <= self.top < self.bottom <= 1):
            raise ValueError("box must be a nonempty normalized top-left rectangle")


@dataclass(frozen=True, slots=True)
class TextSpan:
    id: str
    page: int
    text: str
    box: Box | None
    method: str
    confidence: float | None = None

    def __post_init__(self) -> None:
        if not self.id or self.page < 1 or not self.text.strip():
            raise ValueError("span requires an ID, page number, and text")
        if self.confidence is not None and not 0 <= self.confidence <= 100:
            raise ValueError("OCR confidence must be in [0, 100]")


@dataclass(frozen=True, slots=True)
class DocumentPage:
    number: int
    width_px: int
    height_px: int
    spans: tuple[TextSpan, ...]

    def __post_init__(self) -> None:
        if self.number < 1 or self.width_px < 1 or self.height_px < 1:
            raise ValueError("invalid page dimensions")
        ids = [span.id for span in self.spans]
        if len(ids) != len(set(ids)) or any(span.page != self.number for span in self.spans):
            raise ValueError("span IDs must be unique and belong to this page")


@dataclass(frozen=True, slots=True)
class FieldValue:
    value: str | None
    raw: str | None
    evidence_ids: tuple[str, ...] = ()
    origin: Literal["observed", "computed", "reviewer"] = "observed"
    missing_reason: str | None = None

    def __post_init__(self) -> None:
        if self.value is None and not self.missing_reason:
            raise ValueError("missing value requires a reason")
        if self.value is not None and self.missing_reason:
            raise ValueError("present value cannot have a missing reason")


@dataclass(frozen=True, slots=True)
class LineItem:
    row_id: str
    description: FieldValue
    quantity: FieldValue
    unit_price: FieldValue
    line_total: FieldValue
    tax: FieldValue


@dataclass(frozen=True, slots=True)
class InvoiceRecord:
    schema_version: str
    fields: dict[str, FieldValue]
    line_items: tuple[LineItem, ...]

    def __post_init__(self) -> None:
        if set(self.fields) != set(HEADER_FIELDS):
            raise ValueError("invoice header does not match schema")
        row_ids = [row.row_id for row in self.line_items]
        if len(row_ids) != len(set(row_ids)):
            raise ValueError("line-item row IDs must be unique")

    def to_dict(self) -> dict:
        return asdict(self)


@dataclass(frozen=True, slots=True)
class ValidationIssue:
    code: str
    path: str
    detail: str
    blocking: bool = True


def missing(reason: str = "not_observed") -> FieldValue:
    return FieldValue(value=None, raw=None, missing_reason=reason)

spatial_lines.py:
"""Join disjoint OCR fragments on one visual line without inventing evidence."""

from __future__ import annotations

import re
from dataclasses import dataclass, replace

from .contracts import Box, DocumentPage, FieldValue, TextSpan


@dataclass(frozen=True)
class SpatialLine:
    spans: tuple[TextSpan, ...]

    @property
    def text(self) -> str:
        return " ".join(span.text.strip() for span in self.spans)

    def observed(self, match: re.Match, group: int = 1) -> FieldValue:
        """Cite only fragments intersecting this captured value's text range."""
        start, end = match.span(group)
        offset = 0
        sources = []
        for span in self.spans:
            length = len(span.text.strip())
            if offset < end and offset + length > start:
                sources.append(span)
            offset += length + 1
        return FieldValue(match.group(group).strip(), " ".join(span.text for span in sources),
                          tuple(span.id for span in sources))


def _view_spans(page: DocumentPage) -> tuple[TextSpan, ...]:
    """Use explicit split table headers to orient grouping on sideways rasters.

    This is an extraction-only view: stored OCR boxes and the raster stay intact.
    Without both anchors, leave geometry unchanged rather than guess direction.
    """
    descriptions = [s for s in page.spans if s.box and s.text.strip().casefold() == "description"]
    amounts = [s for s in page.spans if s.box and s.text.strip().casefold() in ("amount", "line total")]
    if len(descriptions) != 1 or len(amounts) != 1:
        return page.spans
    description, amount = descriptions[0].box, amounts[0].box
    assert description and amount
    if ((description.right - description.left) * page.width_px >=
            (description.bottom - description.top) * page.height_px):
        return page.spans
    if abs(description.left - amount.left) > .02:
        return page.spans
    clockwise = description.top > amount.top

    def transform(box: Box) -> Box:
        if clockwise:
            return Box(1 - box.bottom, box.left, 1 - box.top, box.right)
        return Box(box.top, 1 - box.right, box.bottom, 1 - box.left)

    return tuple(replace(s, box=transform(s.box)) if s.box else s for s in page.spans)


def _same_line(left: TextSpan, right: TextSpan) -> bool:
    assert left.box and right.box
    a, b = left.box, right.box
    if a.left < b.right and b.left < a.right:
        return False  # Overlapping boxes are not distinct columns.
    overlap = min(a.bottom, b.bottom) - max(a.top, b.top)
    return overlap >= .5 * min(a.bottom - a.top, b.bottom - b.top)


def spatial_lines(page: DocumentPage) -> tuple[SpatialLine, ...]:
    spans = _view_spans(page)
    long_spans = [s for s in spans if s.box and len(s.text.strip()) >= 6]
    if long_spans and sum(s.box.bottom - s.box.top > s.box.right - s.box.left for s in long_spans) > len(long_spans) / 2:
        # Sideways text without usable header anchors cannot safely be joined
        # by its raw y-coordinate. Preserve the OCR reading order instead.
        return tuple(SpatialLine((span,)) for span in spans)
    positioned = sorted((s for s in spans if s.box),
                        key=lambda s: ((s.box.top + s.box.bottom) / 2, s.box.left))
    groups: list[list[TextSpan]] = []
    for span in positioned:
        if groups and all(_same_line(existing, span) for existing in groups[-1]):
            groups[-1].append(span)
        else:
            groups.append([span])
    # No geometry means no inferred relationship to another span.
    return tuple(SpatialLine(tuple(sorted(group, key=lambda s: s.box.left))) for group in groups) + tuple(
        SpatialLine((span,)) for span in spans if span.box is None
    )

validation.py:
"""Evidence and invoice arithmetic checks. No automatic value correction."""

from __future__ import annotations

import re
from collections.abc import Callable, Sequence
from datetime import date
from decimal import Decimal, InvalidOperation

from .contracts import DocumentPage, FieldValue, InvoiceRecord, HEADER_FIELDS, REQUIRED_FIELDS, ValidationIssue

MONEY = re.compile(r"^-?\d+\.\d{2}$")
QUANTITY = re.compile(r"^\d+(?:\.\d+)?$")
TOLERANCE = Decimal("0.01")


def _decimal(value: FieldValue, *, money: bool) -> Decimal | None:
    if value.value is None:
        return None
    if not (MONEY if money else QUANTITY).fullmatch(value.value):
        return None
    try:
        return Decimal(value.value)
    except InvalidOperation:
        return None


def _all_values(record: InvoiceRecord):
    for name, field in record.fields.items():
        yield f"fields.{name}", field
    for row in record.line_items:
        for name in ("description", "quantity", "unit_price", "line_total", "tax"):
            yield f"line_items.{row.row_id}.{name}", getattr(row, name)


def _evidence_supports(value: str, texts: list[str]) -> bool:
    value = " ".join(value.casefold().split())
    parts = [" ".join(text.casefold().split()) for text in texts]
    if all(value in part for part in parts):
        return True  # Preserve support from repeated complete observations.
    source = " ".join(parts)
    start = source.find(value)
    if start < 0:
        return False
    end = start + len(value)
    offset = 0
    for part in parts:
        if not (offset < end and offset + len(part) > start):
            return False  # An unrelated extra citation is not supporting evidence.
        offset += len(part) + 1
    return True


def validate_invoice(record: InvoiceRecord, page: DocumentPage | Sequence[DocumentPage], *,
                     header_extractor: Callable[[DocumentPage], InvoiceRecord] | None = None) -> tuple[ValidationIssue, ...]:
    issues: list[ValidationIssue] = []
    pages = (page,) if isinstance(page, DocumentPage) else page
    spans = {span.id: span for source_page in pages for span in source_page.spans}
    if len(pages) > 1:
        if header_extractor is None:
            from .baseline import extract_invoice
            header_extractor = extract_invoice
        candidates = [header_extractor(source_page) for source_page in pages]
        for name in HEADER_FIELDS:
            if name == "supplier_name":
                continue  # A continuation page may begin with a line item.
            observed = [candidate.fields[name].value for candidate in candidates]
            if len({value for value in observed if value is not None}) > 1:
                issues.append(ValidationIssue("HEADER_CONFLICT", f"fields.{name}",
                                              "Different observed values appear on separate pages"))
    for name in REQUIRED_FIELDS:
        if record.fields[name].value is None:
            issues.append(ValidationIssue("REQUIRED_MISSING", f"fields.{name}", "Required value was not observed"))
    for path, field in _all_values(record):
        if field.value is None:
            continue
        if not field.evidence_ids and field.origin == "observed":
            issues.append(ValidationIssue("EVIDENCE_MISSING", path, "Observed value has no source span"))
        for span_id in field.evidence_ids:
            span = spans.get(span_id)
            if span is None:
                issues.append(ValidationIssue("EVIDENCE_UNKNOWN", path, f"Unknown span ID: {span_id}"))
        if field.origin == "observed" and field.evidence_ids and all(ref in spans for ref in field.evidence_ids):
            if not _evidence_supports(field.value, [spans[ref].text for ref in field.evidence_ids]):
                issues.append(ValidationIssue("EVIDENCE_MISMATCH", path, "Value does not occur in cited spans"))

    for name in ("subtotal", "tax", "discount", "shipping", "total"):
        field = record.fields[name]
        if field.value is not None and _decimal(field, money=True) is None:
            issues.append(ValidationIssue("INVALID_MONEY", f"fields.{name}", "Expected a decimal with two fractional digits"))
    currency = record.fields["currency"].value
    if currency is not None and currency != "USD":
        issues.append(ValidationIssue("UNSUPPORTED_CURRENCY", "fields.currency", "Phase 0 parser supports explicit USD only"))

    parsed_dates: dict[str, date] = {}
    for name in ("issue_date", "due_date"):
        value = record.fields[name].value
        if value is None:
            continue
        try:
            if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
                raise ValueError("date format must be ISO calendar format")
            parsed_dates[name] = date.fromisoformat(value)
        except ValueError:
            issues.append(ValidationIssue("AMBIGUOUS_DATE", f"fields.{name}", "Expected YYYY-MM-DD"))
    if all(name in parsed_dates for name in ("issue_date", "due_date")) and parsed_dates["due_date"] < parsed_dates["issue_date"]:
        issues.append(ValidationIssue("DATE_ORDER", "fields.due_date", "Due date precedes issue date"))

    if not record.line_items:
        issues.append(ValidationIssue("NO_LINE_ITEMS", "line_items", "No line-item rows were extracted"))
    row_totals: list[Decimal] = []
    for row in record.line_items:
        quantity = _decimal(row.quantity, money=False)
        unit_price = _decimal(row.unit_price, money=True)
        line_total = _decimal(row.line_total, money=True)
        if None in (quantity, unit_price, line_total):
            issues.append(ValidationIssue("INVALID_ROW_AMOUNT", f"line_items.{row.row_id}", "Row numbers could not be parsed"))
            continue
        assert quantity is not None and unit_price is not None and line_total is not None
        row_totals.append(line_total)
        if abs(quantity * unit_price - line_total) > TOLERANCE:
            issues.append(ValidationIssue("ROW_ARITHMETIC_MISMATCH", f"line_items.{row.row_id}", "Quantity times unit price differs from observed row total"))

    subtotal = _decimal(record.fields["subtotal"], money=True)
    if subtotal is not None and len(row_totals) == len(record.line_items) and row_totals:
        if abs(sum(row_totals) - subtotal) > TOLERANCE:
            issues.append(ValidationIssue("SUBTOTAL_MISMATCH", "fields.subtotal", "Observed subtotal differs from sum of observed rows"))
    terms = {name: _decimal(record.fields[name], money=True) for name in ("subtotal", "tax", "discount", "shipping", "total")}
    if all(value is not None for value in terms.values()):
        expected = terms["subtotal"] + terms["tax"] - terms["discount"] + terms["shipping"]
        if abs(expected - terms["total"]) > TOLERANCE:
            issues.append(ValidationIssue("TOTAL_MISMATCH", "fields.total", f"Observed total differs from computed {expected:.2f}"))
    else:
        issues.append(ValidationIssue("TOTAL_NOT_CHECKED", "fields.total", "A total component is missing or invalid", blocking=False))
    return tuple(issues)

spatial_baseline.py:
"""Experimental spatial invoice parser; calibration rejected default promotion."""

from __future__ import annotations

import re
from dataclasses import replace
from .spatial_lines import SpatialLine, spatial_lines

from .contracts import (
    CONTRACT_VERSION,
    HEADER_FIELDS,
    DocumentPage,
    FieldValue,
    InvoiceRecord,
    LineItem,
    TextSpan,
    missing,
)

BASELINE_VERSION = "ocr-rules-v0.4"

LABELS = {
    "invoice_number": re.compile(r"^invoice\s*(?:number|no\.?|#)\s*:\s*(.+)$", re.I),
    "issue_date": re.compile(r"^(?:issue\s*)?date\s*:\s*(.+)$", re.I),
    "due_date": re.compile(r"^due\s*date\s*:\s*(.+)$", re.I),
    "currency": re.compile(r"^currency\s*:\s*(.+)$", re.I),
    "subtotal": re.compile(r"^subtotal\s*:\s*(.+)$", re.I),
    "tax": re.compile(r"^tax\s*:\s*(.+)$", re.I),
    "discount": re.compile(r"^discount\s*:\s*(.+)$", re.I),
    "shipping": re.compile(r"^shipping\s*:\s*(.+)$", re.I),
    "total": re.compile(r"^total\s*:\s*(.+)$", re.I),
}
ROW = re.compile(r"^(.+?)\s+(\d+(?:\.\d+)?)\s+(\d+\.\d{2})\s+(\d+\.\d{2})$")
ROW_WITHOUT_TOTAL = re.compile(r"^(.+?)\s+(\d+(?:\.\d+)?)\s+(\d+\.\d{2})$")
ROW_WITHOUT_QUANTITY = re.compile(r"^(.+?)\s+(\d+\.\d{2})\s+(\d+\.\d{2})$")
AMOUNT_ONLY = re.compile(r"^\d+\.\d{2}$")


def _separate_prices(line: SpatialLine, match: re.Match) -> bool:
    description_ids = set(line.observed(match, 1).evidence_ids)
    price_ids = set(line.observed(match, 2).evidence_ids + line.observed(match, 3).evidence_ids)
    return not description_ids & price_ids and all(
        AMOUNT_ONLY.fullmatch(token) for span in line.spans if span.id in price_ids for token in span.text.split()
    )


def observed(value: str, span: TextSpan) -> FieldValue:
    return FieldValue(value=value.strip(), raw=span.text, evidence_ids=(span.id,))


def extract_invoice(page: DocumentPage) -> InvoiceRecord:
    fields = {name: missing() for name in HEADER_FIELDS}
    for span in page.spans:
        line = span.text.strip()
        if not line:
            continue
        matched = False
        for name, pattern in LABELS.items():
            match = pattern.fullmatch(line)
            if match:
                if fields[name].value is None:
                    fields[name] = observed(match.group(1), span)
                matched = True
                break
        if matched:
            continue
        # Tesseract can emit a clipped page-corner glyph before the actual
        # printed header. A source box touching both top and left edges is
        # unreliable as a supplier name.
        corner_artifact = span.box is not None and span.box.top <= .005 and span.box.left <= .005
        if fields["supplier_name"].value is None and line.lower() != "invoice" and not corner_artifact:
            fields["supplier_name"] = observed(re.sub(r"\s+INVOICE$", "", line, flags=re.I), span)
    lines = spatial_lines(page)
    # Keep directly observed labels first; recover split labels/values only
    # when the field is absent. Never replace a complete observed value.
    for line in lines:
        if len(line.spans) < 2:
            continue
        for name, pattern in LABELS.items():
            match = pattern.fullmatch(line.text)
            if match and fields[name].value is None:
                fields[name] = line.observed(match)
    return InvoiceRecord(CONTRACT_VERSION, fields, _extract_rows(lines))


def extract_invoice_pages(pages: tuple[DocumentPage, ...]) -> InvoiceRecord:
    """Apply the narrow baseline per page, retaining source order and page spans."""
    if not pages:
        raise ValueError("At least one page is required")
    fields = {name: missing() for name in HEADER_FIELDS}
    rows: list[LineItem] = []
    for page in pages:
        candidate = extract_invoice(page)
        for name in HEADER_FIELDS:
            if fields[name].value is None and candidate.fields[name].value is not None:
                fields[name] = candidate.fields[name]
        for row in candidate.line_items:
            rows.append(replace(row, row_id=f"row-{len(rows) + 1:03d}"))
    return InvoiceRecord(CONTRACT_VERSION, fields, tuple(rows))


def _extract_rows(lines: tuple[SpatialLine, ...]) -> tuple[LineItem, ...]:
    candidates: list[LineItem] = []
    for line in lines:
        if any(pattern.fullmatch(line.text) for pattern in LABELS.values()):
            continue
        match = ROW.fullmatch(line.text)
        if match:
            description, quantity, unit_price, total = (line.observed(match, index) for index in range(1, 5))
        else:
            match = ROW_WITHOUT_QUANTITY.fullmatch(line.text)
            # A separate description and two observed prices form a partial
            # row. A single-span two-number line is ambiguous with decimal
            # quantity + unit price, so retain the existing interpretation.
            if match and len(line.spans) >= 2 and _separate_prices(line, match):
                description = line.observed(match, 1)
                quantity = missing("quantity_not_observed")
                unit_price, total = line.observed(match, 2), line.observed(match, 3)
            else:
                match = ROW_WITHOUT_TOTAL.fullmatch(line.text)
                if match is None:
                    continue
                description, quantity, unit_price = (line.observed(match, index) for index in range(1, 4))
                total = missing("rightmost_amount_not_observed")
        row = LineItem(
            row_id="pending",
            description=description,
            quantity=quantity,
            unit_price=unit_price,
            line_total=total,
            tax=missing("not_explicit_on_row"),
        )
        candidates.append(row)
    return tuple(replace(row, row_id=f"row-{index:03d}") for index, row in enumerate(candidates, start=1))

release_scoring.py:
"""Versioned, order-independent invoice scoring for future frozen corpora.

This module scores labels and saved candidate records. It does not run OCR or
inference, and it deliberately leaves the development-v1 scorer unchanged.
"""

from __future__ import annotations

from collections import Counter
from decimal import Decimal, InvalidOperation

from .contracts import HEADER_FIELDS, REQUIRED_FIELDS

SCORING_VERSION = "invoice-release-scoring-v1"
ROW_FIELDS = ("description", "quantity", "unit_price", "line_total", "tax")
NUMERIC_FIELDS = frozenset({"subtotal", "tax", "discount", "shipping", "total",
                            "quantity", "unit_price", "line_total"})
MAX_ROWS = 200


def _normalize(name: str, value: str | None) -> str | None:
    if value is None:
        return None
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a string or null")
    clean = " ".join(value.split())
    if not clean:
        return None
    if name in NUMERIC_FIELDS:
        try:
            number = Decimal(clean)
        except InvalidOperation:
            return clean
        return format(number.normalize(), "f") if number.is_finite() else clean
    return clean.casefold()


def _predicted_value(field: object) -> str | None:
    if field is None:
        return None
    if not isinstance(field, dict):
        raise ValueError("Predicted fields must be objects")
    return field.get("value")


def _counts(gold: str | None, predicted: str | None) -> dict[str, int]:
    if gold is None:
        return {"tp": 0, "fp": int(predicted is not None), "fn": 0}
    if predicted == gold:
        return {"tp": 1, "fp": 0, "fn": 0}
    return {"tp": 0, "fp": int(predicted is not None), "fn": 1}


def _metrics(counts: dict[str, int]) -> dict:
    tp, fp, fn = (counts[key] for key in ("tp", "fp", "fn"))
    precision = tp / (tp + fp) if tp + fp else None
    recall = tp / (tp + fn) if tp + fn else None
    f1 = 2 * tp / (2 * tp + fp + fn) if 2 * tp + fp + fn else None
    return {**counts, "precision": round(precision, 4) if precision is not None else None,
            "recall": round(recall, 4) if recall is not None else None,
            "f1": round(f1, 4) if f1 is not None else None}


def _assignment(cost: list[list[int]]) -> list[int]:
    """Minimum-cost square assignment; returns a column for every row."""
    count = len(cost)
    if count == 0:
        return []
    u = [0] * (count + 1)
    v = [0] * (count + 1)
    assigned_row = [0] * (count + 1)
    previous = [0] * (count + 1)
    for row in range(1, count + 1):
        assigned_row[0] = row
        column = 0
        minimum = [float("inf")] * (count + 1)
        used = [False] * (count + 1)
        while True:
            used[column] = True
            current_row = assigned_row[column]
            delta = float("inf")
            next_column = 0
            for candidate in range(1, count + 1):
                if used[candidate]:
                    continue
                reduced = cost[current_row - 1][candidate - 1] - u[current_row] - v[candidate]
                if reduced < minimum[candidate]:
                    minimum[candidate] = reduced
                    previous[candidate] = column
                if minimum[candidate] < delta:
                    delta = minimum[candidate]
                    next_column = candidate
            for candidate in range(count + 1):
                if used[candidate]:
                    u[assigned_row[candidate]] += delta
                    v[candidate] -= delta
                else:
                    minimum[candidate] -= delta
            column = next_column
            if assigned_row[column] == 0:
                break
        while True:
            old_column = previous[column]
            assigned_row[column] = assigned_row[old_column]
            column = old_column
            if column == 0:
                break
    result = [-1] * count
    for column in range(1, count + 1):
        result[assigned_row[column] - 1] = column - 1
    return result


def _match_rows(gold: list[dict], predicted: list[dict]) -> list[tuple[int, int]]:
    count = max(len(gold), len(predicted))
    if count == 0:
        return []
    weights = {"description": 3, "quantity": 1, "unit_price": 1, "line_total": 2, "tax": 1}
    # One extra matched row always wins over a better partial match elsewhere.
    match_bonus = (sum(weights.values()) + 1) * count + 1
    benefit = [[0] * count for _ in range(count)]
    for gi, left in enumerate(gold):
        for pi, right in enumerate(predicted):
            description = left["description"] is not None and left["description"] == right["description"]
            amounts = all(left[key] is not None and left[key] == right[key]
                          for key in ("quantity", "unit_price", "line_total"))
            if description or amounts:
                benefit[gi][pi] = match_bonus + sum(weight for key, weight in weights.items()
                                                    if left[key] is not None and left[key] == right[key])
    selected = _assignment([[-value for value in row] for row in benefit])
    return [(gi, pi) for gi, pi in enumerate(selected[:len(gold)])
            if pi < len(predicted) and benefit[gi][pi] > 0]


def score_invoice(gold: dict, prediction: dict | None) -> dict:
    """Score one invoice; `None` is a failed extraction, not an omitted document."""
    if not isinstance(gold, dict) or set(gold.get("fields", {})) != set(HEADER_FIELDS):
        raise ValueError("Gold invoice must label every header field, using null for absent values")
    exclusions = gold.get("field_exclusions", {})
    if (not isinstance(exclusions, dict) or not set(exclusions).issubset(HEADER_FIELDS) or
            any(not isinstance(reason, str) or not reason.strip() for reason in exclusions.values())):
        raise ValueError("Field exclusions need named invoice fields and nonempty reasons")
    record = prediction.get("record") if prediction is not None and "record" in prediction else prediction
    if record is not None and (not isinstance(record, dict) or not isinstance(record.get("fields"), dict)):
        raise ValueError("Prediction must be an invoice record or contain a record")
    gold_rows = gold.get("line_items")
    predicted_rows = record.get("line_items", []) if record is not None else []
    if not isinstance(gold_rows, (list, tuple)) or not isinstance(predicted_rows, (list, tuple)):
        raise ValueError("Line items must be lists or tuples")
    if len(gold_rows) > MAX_ROWS or len(predicted_rows) > MAX_ROWS:
        raise ValueError("Invoice row count exceeds scoring limit")
    if not isinstance(gold.get("id"), str) or not gold["id"]:
        raise ValueError("Gold document ID is required")

    gold_fields = {name: _normalize(name, gold["fields"][name]) for name in HEADER_FIELDS}
    for name in sorted(NUMERIC_FIELDS & set(HEADER_FIELDS)):
        if gold_fields[name] is not None:
            try:
                number = Decimal(gold_fields[name])
            except InvalidOperation as exc:
                raise ValueError(f"Invalid gold amount: {name}") from exc
            if not number.is_finite():
                raise ValueError(f"Invalid gold amount: {name}")
    predicted_fields = {name: _normalize(name, _predicted_value(record["fields"].get(name)))
                        for name in HEADER_FIELDS} if record is not None else {name: None for name in HEADER_FIELDS}
    header = {name: ({"tp": 0, "fp": 0, "fn": 0} if name in exclusions else
                     _counts(gold_fields[name], predicted_fields[name])) for name in HEADER_FIELDS}

    def normalize_row(row: dict, *, candidate: bool) -> dict:
        if not isinstance(row, dict):
            raise ValueError("Each line item must be an object")
        return {name: _normalize(name, _predicted_value(row.get(name)) if candidate else row.get(name))
                for name in ROW_FIELDS}

    expected = [normalize_row(row, candidate=False) for row in gold_rows]
    actual = [normalize_row(row, candidate=True) for row in predicted_rows]
    for row in expected:
        for name in sorted(NUMERIC_FIELDS & set(ROW_FIELDS)):
            if row[name] is not None:
                try:
                    number = Decimal(row[name])
                except InvalidOperation as exc:
                    raise ValueError(f"Invalid gold row amount: {name}") from exc
                if not number.is_finite():
                    raise ValueError(f"Invalid gold row amount: {name}")
    matches = _match_rows(expected, actual)
    paired_gold = {gi for gi, _ in matches}
    paired_predicted = {pi for _, pi in matches}
    row_cells = {name: {"tp": 0, "fp": 0, "fn": 0} for name in ROW_FIELDS}
    exact_rows = 0
    for gi, pi in matches:
        exact_rows += int(all(expected[gi][name] == actual[pi][name] for name in ROW_FIELDS))
        for name in ROW_FIELDS:
            row_cells[name].update({key: row_cells[name][key] + value for key, value in
                                    _counts(expected[gi][name], actual[pi][name]).items()})
    for gi, row in enumerate(expected):
        if gi not in paired_gold:
            for name in ROW_FIELDS:
                row_cells[name]["fn"] += int(row[name] is not None)
    for pi, row in enumerate(actual):
        if pi not in paired_predicted:
            for name in ROW_FIELDS:
                row_cells[name]["fp"] += int(row[name] is not None)
    return {
        "id": gold["id"], "family_group": gold.get("family_group"),
        "processed": record is not None,
        "header": header,
        "excluded_header_fields": dict(exclusions),
        "required_all_exact": None if set(REQUIRED_FIELDS) & set(exclusions) else
                              (record is not None and all(gold_fields[name] is not None and
                                                       gold_fields[name] == predicted_fields[name]
                                                       for name in REQUIRED_FIELDS)),
        "gold_rows": len(expected), "predicted_rows": len(actual),
        "matched_rows": len(matches), "exact_rows": exact_rows,
        "row_matches": [{"gold_index": gi, "predicted_index": pi} for gi, pi in matches],
        "row_cells": row_cells,
        "failure_type": prediction.get("failure_type", "MissingPrediction")
                        if record is None and isinstance(prediction, dict) else
                        "MissingPrediction" if record is None else None,
    }


def summarize_invoices(scores: list[dict]) -> dict:
    """Aggregate a scheduled split, including failed documents in all counts."""
    if not scores or len({score["id"] for score in scores}) != len(scores):
        raise ValueError("A nonempty set of unique document scores is required")
    header = {name: {key: sum(score["header"][name][key] for score in scores)
                     for key in ("tp", "fp", "fn")} for name in HEADER_FIELDS}
    row_cells = {name: {key: sum(score["row_cells"][name][key] for score in scores)
                        for key in ("tp", "fp", "fn")} for name in ROW_FIELDS}
    row_detection = {"tp": sum(score["matched_rows"] for score in scores),
                     "fp": sum(score["predicted_rows"] - score["matched_rows"] for score in scores),
                     "fn": sum(score["gold_rows"] - score["matched_rows"] for score in scores)}
    exact_rows = {"tp": sum(score["exact_rows"] for score in scores),
                  "fp": sum(score["predicted_rows"] - score["exact_rows"] for score in scores),
                  "fn": sum(score["gold_rows"] - score["exact_rows"] for score in scores)}
    field_metrics = {name: _metrics(counts) for name, counts in header.items()}
    eligible_f1 = [2 * counts["tp"] / denominator for counts in header.values()
                   if (denominator := 2 * counts["tp"] + counts["fp"] + counts["fn"])]
    return {
        "scoring_version": SCORING_VERSION,
        "documents_scheduled": len(scores),
        "documents_processed": sum(score["processed"] for score in scores),
        "all_required_exact": {"correct": sum(score["required_all_exact"] is True for score in scores),
                               "eligible": sum(score["required_all_exact"] is not None for score in scores)},
        "header_field_exclusions": {name: sum(name in score["excluded_header_fields"] for score in scores)
                                    for name in HEADER_FIELDS},
        "header_fields": field_metrics,
        "header_macro_f1": round(sum(eligible_f1) / len(eligible_f1), 4) if eligible_f1 else None,
        "row_detection": _metrics(row_detection),
        "row_exact": _metrics(exact_rows),
        "row_fields": {name: _metrics(counts) for name, counts in row_cells.items()},
        "failures_by_type": dict(sorted(Counter(score["failure_type"] for score in scores
                                                if not score["processed"]).items())),
    }
